B=[['拉丁 ius 法、权利 + dicere 说的词根 → iudex，属格 iudicis','作出法律判定的人；法官']]
V=B+[['拉丁 iudicare → 古法语 jugier／盎格鲁法语 juger','审断、评价'],['中古英语 jugen → 英语 judge 动词','判断；评定；审判']]
J=B+[['拉丁 iudicare → 古法语 jugier → jugement','判断这一动作及其结果'],['中古英语 juggement → 英语 judgment／judgement','判决；判断；判断力']]
JUDICIAL=B+[['拉丁 iudicium 判决 → iudicialis','与审判有关的'],['英语 judicial','司法的；法院或法官的']]
WISE=B+[['拉丁 iudicium → 中世纪拉丁 iudiciosus','有判断力的、审慎的'],['法语 judicieux／直接拉丁借入 → 英语 judicious','判断稳妥、处理得当的']]
PREJ=B+[['拉丁 prae- 事先 + iudicium → praeiudicium','预先裁断；也有损害之义'],['古法语 prejudice／中世纪拉丁 prejudicium → 中古英语 prejudice','损害；先入之见'],['英语 prejudice 名词；动词由名词及古法语 prejudiciier 而来','偏见；损害；使带有偏见']]
PREV=B+[['拉丁 praeiudicare → 中古法语 préjuger','事先作判断'],['英语 prejudge','未充分了解就预先下结论']]
ADJUD=B+[['拉丁 ad- + iudicare → adiudicare；分词 adiudicatus','判给；作出裁决']]
DECISION=ADJUD+[['晚期拉丁 adiudicatio／adiudication- → 法语 adjudication／直接借入英语','裁决这一过程或结果'],['英语 adjudication','正式评审、裁决']]
ADJUDICATE=ADJUD+[['拉丁分词 adiudicatus；或英语 adjudication 的逆构','英语动词来源有两种分析'],['英语 adjudicate','正式评审或裁决']]
